SELECT s.customer,i.item_code,SUM(i.qty) AS qty,SUM(i.amount) AS amount FROM "tabSales Invoice" s JOIN "tabSales Invoice Item" i ON i.parent=s.name AND i.parenttype='Sales Invoice' WHERE s.docstatus=1 AND (%(company)s='' OR s.company=%(company)s) AND (%(from_date)s='' OR s.posting_date>=%(from_date)s) AND (%(to_date)s='' OR s.posting_date<=%(to_date)s) GROUP BY s.customer,i.item_code ORDER BY amount DESC
